    "Date =\nADDCOLUMNS(\n    CALENDAR(DATE(2024, 1, 1), DATE(2025, 12, 31)),\n    \"Year\", YEAR([Date]),\n    \"Quarter\", \"Q\" & QUARTER([Date]),\n    \"Month\", FORMAT([Date], \"MMM\"),\n    \"MonthNo\", MONTH([Date]),\n    \"YearMonth\", FORMAT([Date], \"yyyy-MM\")\n)",
